import{_ as t,a as r,c as a,ac as i}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","description":"辨清彖、象、系辞的上下篇与大象小象，逐篇说明文言、说卦、序卦、杂卦的阅读任务、原文例子和解释边界。","frontmatter":{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","description":"辨清彖、象、系辞的上下篇与大象小象，逐篇说明文言、说卦、序卦、杂卦的阅读任务、原文例子和解释边界。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"辨清彖、象、系辞的上下篇与大象小象，逐篇说明文言、说卦、序卦、杂卦的阅读任务、原文例子和解释边界。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"},{"title":"阿甘正传","link":"/life/personal/media/movies/forrest-gump","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后","link":"/life/personal/yijing/hexagrams-57-64-part-03"},"next":{"text":"同一句《易》，为何有不同解释：历代注家对读","link":"/life/personal/yijing/commentaries"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 63 既济：完成之后仍要照料至读完六十四卦之后","link":"/life/personal/yijing/hexagrams-57-64-part-03"},"next":{"text":"同一句《易》，为何有不同解释：历代注家对读","link":"/life/personal/yijing/commentaries"}},"headers":[],"relativePath":"life/personal/yijing/ten-wings.md","filePath":"life/personal/yijing/ten-wings.md"}'),n={name:"life/personal/yijing/ten-wings.md"};function o(l,e,d,h,p,s){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="《十翼》逐篇阅读-七种十篇怎样帮助理解《周易》" tabindex="-1">《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》 <a class="header-anchor" href="#《十翼》逐篇阅读-七种十篇怎样帮助理解《周易》" aria-label="Permalink to &quot;《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》&quot;">​</a></h1><p>《易传》不是一部格式一致的逐字注释。它包含释卦、释爻、观象修养、取象目录、卦序说明和关于《易》的整体论述。先认出每一篇在做什么，才不会拿《序卦》的连接词当作历史定律，或用《说卦》的一个物象代替整段经文。</p><p>“十翼”是传统总称，作者传统归于孔子；本文不把这个归属等同于现存十篇由孔子在同一时期亲笔完成。相关成书问题见<a href="/life/personal/yijing/text-history">经、传、注与文本史</a>。</p><h2 id="七种为什么算成十篇" tabindex="-1">七种为什么算成十篇 <a class="header-anchor" href="#七种为什么算成十篇" aria-label="Permalink to &quot;七种为什么算成十篇&quot;">​</a></h2><table tabindex="0"><thead><tr><th>种类</th><th style="text-align:right;">篇数</th><th>主要对象</th><th>初读的任务</th></tr></thead><tbody><tr><td>《彖传》</td><td style="text-align:right;">上、下二篇</td><td>六十四卦的卦辞及全卦结构</td><td>看整体判断如何被解释</td></tr><tr><td>《象传》</td><td style="text-align:right;">上、下二篇</td><td>每卦大象及各爻小象</td><td>看卦象、爻位怎样引出行动要求</td></tr><tr><td>《系辞传》</td><td style="text-align:right;">上、下二篇</td><td>《易》的性质、符号、筮法、德行与变化</td><td>建立词义与方法意识</td></tr><tr><td>《文言传》</td><td style="text-align:right;">一篇</td><td>乾、坤两卦</td><td>看基本词语怎样变为德行论述</td></tr><tr><td>《说卦传》</td><td style="text-align:right;">一篇</td><td>八卦性质、方位和取象</td><td>建立取象词表并辨别分类层次</td></tr><tr><td>《序卦传》</td><td style="text-align:right;">一篇</td><td>通行六十四卦的先后关系</td><td>看相邻卦如何被串联</td></tr><tr><td>《杂卦传》</td><td style="text-align:right;">一篇</td><td>卦义之间的对照</td><td>用差异检查过度概括</td></tr></tbody></table><p>合计为二加二加二加一加一加一加一，共十篇。“七种”不是少了三篇，而是把分上下的三种各算作一个名称。</p><p><strong>《象上》《象下》不等于《大象》《小象》。</strong> 上、下对应上经和下经；每部分都包含解释全卦的大象与解释爻辞的小象。有些网站为了检索方便，把所有大象另列一页、所有小象另列一页，这只是现代展示方式，不能据此重新计算十翼。</p><h2 id="第一、二翼-《彖上》《彖下》——从一卦总体发问" tabindex="-1">第一、二翼：《彖上》《彖下》——从一卦总体发问 <a class="header-anchor" href="#第一、二翼-《彖上》《彖下》——从一卦总体发问" aria-label="Permalink to &quot;第一、二翼：《彖上》《彖下》——从一卦总体发问&quot;">​</a></h2><p>“彖”在不同语境中需要辨认。注家说“彖辞”，有时指卦下的卦辞；“彖曰”后面的解释则属于《彖传》。在乾卦中，“元亨利贞”与“大哉乾元”相邻，也不能因此合称同一条卦辞。</p><p>《彖上》随上经解释乾至离三十卦；《彖下》随下经解释咸至未济三十四卦。阅读时可找三种证据：第一，对卦名或字义的解释；第二，上下卦的性质和关系；第三，某个爻的中、正、应等位置关系。三种手段经常同时使用，不是每卦都套同一种公式。</p><p>例如蒙卦《彖》说“险而止，蒙”，又说“以亨行，时中也”。这里既从坎险、艮止说明卦体，又以是否合时解释其行动。未济卦《彖》说“虽不当位，刚柔应也”，则把位置上的不当与关系上的相应并列。它没有看到一项不利条件便终止判断。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%BD%96" target="_blank" rel="noopener noreferrer">原文：《彖》蒙、未济各段</a>。</p><p>练习时把经文和《彖》分两列。左边只写判断，如“亨”“利涉大川”；右边写传文给出的理由。若右栏使用了左栏没有的宇宙论或伦理概念，就标出“解释的展开”。这比把传文直接当成卦辞的白话翻译更准确。</p><h2 id="第三、四翼-《象上》《象下》——观象之后-人要做什么" tabindex="-1">第三、四翼：《象上》《象下》——观象之后，人要做什么 <a class="header-anchor" href="#第三、四翼-《象上》《象下》——观象之后-人要做什么" aria-label="Permalink to &quot;第三、四翼：《象上》《象下》——观象之后，人要做什么&quot;">​</a></h2><p>大象常有“某象，某卦；君子以……”的结构。但行动主体也可能是“先王”“后”等，内容会涉及礼制、治理、刑狱或资源分配，不能全部改写为个人励志。</p><p>乾的“天行健”引出自强，坤的“地势坤”引出厚德；谦的大象则说“裒多益寡，称物平施”，把山在地中的形象转向调节多寡的行动。观象不是停在“自然景物像什么”，还要问“传文要求谁做何事”。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E8%B1%A1" target="_blank" rel="noopener noreferrer">《大象》乾、坤、谦</a>。</p><p>小象往往用很短的句子说明一爻的理由。例如乾上九“亢龙有悔”，小象释为“盈不可久也”；坤六四“括囊，无咎无誉”，小象说“慎不害也”。它们并非把爻辞简单重复一遍，而是在回答“为什么如此判断”。有时原因是爻位，有时是志向、行为或所处时势。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E8%B1%A1" target="_blank" rel="noopener noreferrer">《小象》</a>。</p><p>一个容易误读的例子是需卦的大象：“君子以饮食宴乐。”如果只把《易》读成无休止的奋斗，它似乎不够积极；放回云在天上、条件尚待成熟的情境，却能看见安顿生活、保存力量也可以成为恰当行动。因此“君子以”之后并不总是立即进取。</p><h2 id="第五、六翼-《系辞上》《系辞下》——一部书怎样说明自己" tabindex="-1">第五、六翼：《系辞上》《系辞下》——一部书怎样说明自己 <a class="header-anchor" href="#第五、六翼-《系辞上》《系辞下》——一部书怎样说明自己" aria-label="Permalink to &quot;第五、六翼：《系辞上》《系辞下》——一部书怎样说明自己&quot;">​</a></h2><p>《系辞》主题广、段落之间有交叠。不能简单说“上篇讲宇宙，下篇讲人生”；孔颖达《正义》就反对以上篇大理、下篇小理来机械分篇，指出两篇都谈到不同层级的问题。不同版本的章数划分也不完全一致，所以查引文最好同时记录开头数个字。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%B3%A8%E7%96%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B711" target="_blank" rel="noopener noreferrer">《周易注疏》卷十一篇题疏</a>。</p><h3 id="《系辞上》的五条阅读线索" tabindex="-1">《系辞上》的五条阅读线索 <a class="header-anchor" href="#《系辞上》的五条阅读线索" aria-label="Permalink to &quot;《系辞上》的五条阅读线索&quot;">​</a></h3><table tabindex="0"><thead><tr><th>线索</th><th>原文入口</th><th>可以提出的问题</th></tr></thead><tbody><tr><td>乾坤与变化</td><td>“天尊地卑，乾坤定矣”</td><td>自然秩序怎样与社会秩序相连？</td></tr><tr><td>观象与玩辞</td><td>“居则观其象而玩其辞”</td><td>阅读时怎样反复揣摩，而非只找结论？</td></tr><tr><td>吉凶与过失</td><td>“无咎者，善补过也”</td><td>无咎是否必然表示毫无风险？</td></tr><tr><td>道与生生</td><td>“一阴一阳之谓道”“生生之谓易”</td><td>变化怎样被理解为持续生成？</td></tr><tr><td>数与筮法</td><td>“大衍之数五十”</td><td>原文给出了哪些程序，哪些细节仍待解释？</td></tr></tbody></table><p>这些入口分别出现在《系辞上》的不同段落。“神”“道”“象”“数”在这里具有古代思想语境，不能直接替换成今天物理学或计算机科学的术语。若发现形式相似，可以作比较；要主张历史来源，则必须另有传播和技术证据。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E7%B9%AB%E8%BE%AD%E4%B8%8A" target="_blank" rel="noopener noreferrer">《系辞上》全文</a>。</p><h3 id="《系辞下》的四条阅读线索" tabindex="-1">《系辞下》的四条阅读线索 <a class="header-anchor" href="#《系辞下》的四条阅读线索" aria-label="Permalink to &quot;《系辞下》的四条阅读线索&quot;">​</a></h3><p>第一是“变通者，趣时者也”，把变化与适时行动联系起来。第二是包牺、神农等文明起源叙述，通过“盖取诸”把器物制度联系于卦象；它是取象式文明解释，不能直接当作各项技术发明的实证编年史。第三是用古经个别辞句讨论人的行为，例如借否九五说明安而不忘危。第四是九卦德论，把履、谦、复、恒、损、益、困、井、巽组织成修养次序。</p><p>《系辞下》又说“不可为典要，唯变所适”，但紧接着也讲“其出入以度”，并不是取消一切尺度。若只记住“变”，就可能把随机改变包装成智慧；若只记住“常”，又会把已有做法固定成永远正确。阅读的任务，是同时保留适时调整与行为尺度。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E7%B9%AB%E8%BE%AD%E4%B8%8B" target="_blank" rel="noopener noreferrer">《系辞下》相关段落</a>。</p><h2 id="第七翼-《文言》——只讲乾坤-却不只解释几个字" tabindex="-1">第七翼：《文言》——只讲乾坤，却不只解释几个字 <a class="header-anchor" href="#第七翼-《文言》——只讲乾坤-却不只解释几个字" aria-label="Permalink to &quot;第七翼：《文言》——只讲乾坤，却不只解释几个字&quot;">​</a></h2><p>《文言》专门展开乾、坤。它反复解释乾六爻，并非每重复一次便提供完全相同的释义，而是从德行、时势、进退、学习等角度再次说明。同一句话在不同段落承担不同论证功能，初读时不要急于删去所谓重复。</p><p>“元者，善之长也”一段把元亨利贞联系到仁、礼、义及处事根基；“君子学以聚之，问以辩之”一段则把九二与学习、辨问、宽居、仁行相连。坤的“至柔而动也刚”，提醒读者柔顺并不等于没有力量；“敬以直内，义以方外”进一步把“直方大”转为内在态度与外在行动的要求。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%96%87%E8%A8%80" target="_blank" rel="noopener noreferrer">《文言》乾、坤两部分</a>。</p><p>阅读时可以问：若把原爻辞遮住，传文还能独立成为一段伦理论述吗？如果能，便能看见传文已经不只是释字，还在建构思想。理解这点也有助于比较<a href="/life/personal/yijing/commentaries">程颐与朱熹的解释方法</a>。</p><h2 id="第八翼-《说卦》——取象目录并不是随意联想许可证" tabindex="-1">第八翼：《说卦》——取象目录并不是随意联想许可证 <a class="header-anchor" href="#第八翼-《说卦》——取象目录并不是随意联想许可证" aria-label="Permalink to &quot;第八翼：《说卦》——取象目录并不是随意联想许可证&quot;">​</a></h2><p>《说卦》先讲作易、三才与阴阳刚柔仁义，再讨论八卦关系、方位、性质及各类物象。例如“乾，健也；坤，顺也”“艮，止也；兑，说也”属于卦德说明；天、地、水、火等是自然物象；父母子女又是家庭秩序中的比拟。这些项目不在同一逻辑层级，做表时应分栏，不能混成一种永远相同的实体。</p><p>这里的“离，丽也”有附丽之义，“兑，说也”的“说”读作悦。若按现代常用义把离直接解释为离开、说直接解释为说话，就会在最基础处走偏。取象列表需要结合原句和古义阅读。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E8%AA%AA%E5%8D%A6" target="_blank" rel="noopener noreferrer">《说卦》</a>。</p><p>《说卦》里的相关排列后来成为先天、后天图式解释的重要材料，但今天熟悉的成套圆图、配色及数字标法不能一律说成现存《说卦》原图。更不能因为乾可取父、天、马等象，就在一次解释中随意切换所指，直到碰上想要的答案。合理的解释必须说明为何此处选择这一象，并检验其是否与经文其他部分相合。</p><h2 id="第九翼-《序卦》——理解一种次序-不是给万事规定流程" tabindex="-1">第九翼：《序卦》——理解一种次序，不是给万事规定流程 <a class="header-anchor" href="#第九翼-《序卦》——理解一种次序-不是给万事规定流程" aria-label="Permalink to &quot;第九翼：《序卦》——理解一种次序，不是给万事规定流程&quot;">​</a></h2><p>《序卦》常用“故受之以”把一卦接到下一卦：物生而幼稚，所以接蒙；幼稚须养，所以接需；有大不宜盈，所以接谦。它既使用卦名词义，也借助社会经验与反转关系，让通行卦序变得可以讲述和记忆。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E5%BA%8F%E5%8D%A6" target="_blank" rel="noopener noreferrer">《序卦》</a>。</p><p>但“饮食必有讼”不是说每次聚餐必有诉讼；“物不可以终通”也不是提供一个可计算的衰退日期。它们是围绕卦序展开的解释性连接。读者可以欣赏其组织能力，同时检查是否存在其他同样说得通的连接。能够另外编出一套流畅故事，并不证明新故事就是古经原意。</p><p>上篇以天地、万物开头，下篇以男女、夫妇、父子、君臣等关系展开，能看出自然与人伦相互说明的思想取向。其中有古代等级和性别结构，现代使用时应说明历史背景，不能把一切既有角色关系自然化为不可改变的规范。</p><h2 id="第十翼-《杂卦》——用差异抵抗-一句话包打天下" tabindex="-1">第十翼：《杂卦》——用差异抵抗“一句话包打天下” <a class="header-anchor" href="#第十翼-《杂卦》——用差异抵抗-一句话包打天下" aria-label="Permalink to &quot;第十翼：《杂卦》——用差异抵抗“一句话包打天下”&quot;">​</a></h2><p>《杂卦》常把两卦并置，例如“乾刚坤柔”“震起也，艮止也”“革去故也，鼎取新也”。它不按六十四卦通常的顺序逐个展开，而以简洁对照抓住区别，特别适合在读过若干卦后复习。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E9%9B%9C%E5%8D%A6" target="_blank" rel="noopener noreferrer">《杂卦》</a>。</p><p>这些短语不是每一卦唯一的定义。《杂卦》说“需不进也”，大象说饮食宴乐，卦辞又有“利涉大川”；若把“不进”当成永远不行动，便无法容纳同卦其余文字。更好的理解是：不同文句突出不同条件，须回到整体确认等待与行动各适用于何时。</p><h2 id="把十翼读成一组问题" tabindex="-1">把十翼读成一组问题 <a class="header-anchor" href="#把十翼读成一组问题" aria-label="Permalink to &quot;把十翼读成一组问题&quot;">​</a></h2><p>选蒙、需、泰、既济中的一卦，依次写六句话：卦爻辞呈现什么；《彖》如何解释全局；大象要求何种行动；小象说明哪项理由；《序卦》怎样接入前后；《杂卦》怎样与别卦比较。如果相关篇没有直接解释，就明确写“本次未找到”，不要补造对应。</p><p>本篇实际核读了上述各篇相关段落，并以《注疏》卷十一复核《系辞》分篇问题。数字文本的章节划分和个别断句可能不同，引用应优先用篇名、卦名与句首定位。继续可读<a href="/life/personal/yijing/philosophy">从经传到思想的层次</a>、<a href="/life/personal/yijing/divination">蓍草与钱币的算法边界</a>或<a href="/life/personal/yijing/reading-practice">六卦对读练习</a>。<a href="/life/personal/yijing/overview">返回易经专题</a>。</p>',43)])])}const f=t(n,[["render",o]]);export{c as __pageData,f as default};
